/* Toast */
.updated-admin .toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(14px) scale(0.94);
  display: inline-flex;
  align-items: center;
  gap: 10px;
  max-width: min(520px, calc(100vw - 32px));
  background: var(--text);
  color: #fff;
  padding: 10px 16px 10px 12px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.35;
  box-shadow: 0 12px 32px rgba(16, 35, 63, 0.28);
  opacity: 0;
  pointer-events: none;
  z-index: 1000;
}

.updated-admin .toast__icon {
  width: 22px;
  height: 22px;
  flex: 0 0 22px;
  border-radius: 50%;
  background: #2b8f5b;
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 12px;
  font-weight: 800;
}

.updated-admin .toast--show {
  opacity: 1;
}

.updated-admin--client-profile .toast {
  top: 70px;
  bottom: auto;
  z-index: 260;
  transform: translateX(-50%) translateY(-8px) scale(0.96);
}

@keyframes popin {
  from {
    opacity: 0;
    transform: scale(0.94);
  }

  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes fadein {
  from {
    opacity: 0;
    transform: translateY(6px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

